CREATE OR REPLACE FUNCTION public.set_staff_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Cannot change your own role'; END IF; DELETE FROM public.staff_invitations WHERE email IN (SELECT lower(email) FROM auth.users WHERE id=target_user); DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role); END $$;
